import re

def validate_input(input_string):
    uid1 = r"{894DF8ED-0BCD-4BDD-99E6-8BD17CF61AE3}"
    uid2 = r"{2286EE88-8537-4B44-8571-B6F96DC904F9}"
    pattern = r"({})\s*({})".format(uid1, uid2)
    if re.match(pattern, input_string):
        return "Access Granted"
    else:
        return "Access Denied"

def main():
    user_input = input("Enter the UID's (separated by a space): ")
    print(validate_input(user_input))

if __name__ == "__main__":
    main()

